You mean you enlarged the overlay file too?
The size is hardcoded in the method that sets the frame. Change the size (make a plugin). Like change that w and h to bigger than 96
Sprite_StateOverlay.prototype.updateFrame = function() {
if (this._overlayIndex > 0) {
const w = 96;
const h = 96;
const sx = this._pattern * w;
const sy = (this._overlayIndex - 1) * h;
this.setFrame(sx, sy, w, h);
} else {
this.setFrame(0, 0, 0, 0);
}
};
